            new() { Id = 5, Name = "Dr. Lisa Park", Title = "Professor", Bio = "Dr. Park is an experimental physicist specializing in quantum optics. She leads a research group studying photon entanglement and its applications in quantum computing.", Email = "l.park@university.edu" },
            new() { Id = 6, Name = "Dr. David Kim", Title = "Associate Professor", Bio = "Dr. Kim is a historian of modern East Asia with particular expertise in 20th-century Korea and Japan. He has authored two books and regularly contributes to public history projects.", Email = "d.kim@university.edu" },
            new() { Id = 7, Name = "Dr. Anna Petrov", Title = "Assistant Professor", Bio = "Dr. Petrov studies molecular biology and genetics. Her current research focuses on gene expression regulation in cancer cells. She completed postdoctoral work at the NIH.", Email = "a.petrov@university.edu" },
