            new() { Id = 1, Title = "Introduction to Computer Science", Code = "CS 101", Description = "A broad introduction to computer science covering programming fundamentals, data representation, algorithms, and computational thinking. Students will complete hands-on projects using Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = instructors[0], IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithms (sorting, searching, graph traversal). Emphasis on time and space complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Hall 305", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = instructors[1], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 72 },
            new() { Id = 3, Title = "Artificial Intelligence", Code = "CS 440", Description = "Covers search algorithms, knowledge representation, machine learning fundamentals, neural networks, and natural language processing. Includes a semester-long team project building an intelligent agent.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Center 110", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = instructors[0], IsFeatured = true, MaxEnrollment = 60, CurrentEnrollment = 55 },

            // Mathematics
            new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics. Prerequisite: precalculus or equivalent.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 101", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = instructors[2], IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
