            // English
            new() { Id = 7, Title = "Creative Writing Workshop", Code = "ENG 215", Description = "An intensive workshop in fiction and creative nonfiction. Students produce original work, participate in peer critique sessions, and study published authors' craft techniques.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Humanities 402", DepartmentId = 3, DepartmentName = "English", Instructor = instructors[3], IsFeatured = true, MaxEnrollment = 25, CurrentEnrollment = 24 },
            new() { Id = 8, Title = "American Literature Survey", Code = "ENG 310", Description = "A survey of major works in American literature from the colonial period to the present, examining themes of identity, democracy, and cultural conflict.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Location = "Humanities 210", DepartmentId = 3, DepartmentName = "English", Instructor = instructors[3], IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 },

            // Physics
            new() { Id = 9, Title = "General Physics I", Code = "PHYS 101", Description = "Mechanics, waves, and thermodynamics. Calculus-based approach with weekly lab sessions. Covers Newton's laws, energy conservation, rotational dynamics, and wave phenomena.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", Location = "Physics Lab 100", DepartmentId = 4, DepartmentName = "Physics", Instructor = instructors[4], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 70 },
            new() { Id = 10, Title = "Quantum Mechanics", Code = "PHYS 430", Description = "Wave-particle duality, Schrödinger equation, quantum states, measurement theory, angular momentum, and hydrogen atom. Prerequisites: PHYS 201 and MATH 220.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Physics Lab 310", DepartmentId = 4, DepartmentName = "Physics", Instructor = instructors[4], IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 28 },

            // History
