            new() { Id = 12, Title = "Modern East Asian History", Code = "HIST 345", Description = "Political, social, and cultural history of China, Japan, and Korea from the 19th century to the present. Explores modernization, revolution, war, and economic transformation.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", Location = "Liberal Arts 220", DepartmentId = 5, DepartmentName = "History", Instructor = instructors[5], IsFeatured = false, MaxEnrollment = 45, CurrentEnrollment = 38 },

            // Biology
            new() { Id = 13, Title = "Introduction to Biology", Code = "BIO 101", Description = "Foundational concepts in biology including cell structure, genetics, evolution, ecology, and physiology. Includes weekly lab sessions with microscopy and dissection.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Tue Lab 1:00–3:50 PM", Location = "Life Sciences 100", DepartmentId = 6, DepartmentName = "Biology", Instructor = instructors[6], IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 88 },
            new() { Id = 14, Title = "Molecular Biology", Code = "BIO 320", Description = "DNA replication, transcription, translation, gene regulation, and recombinant DNA technology. Covers CRISPR, PCR, and modern genomic techniques. Prerequisites: BIO 101 and CHEM 201.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Life Sciences 305", DepartmentId = 6, DepartmentName = "Biology", Instructor = instructors[6], IsFeatured = true, MaxEnrollment = 50, CurrentEnrollment = 42 },
        ];
    }

    public IReadOnlyList<Department> GetDepartments() => _departments.AsReadOnly();

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null, int? minCredits = null, int? maxCredits = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (minCredits.HasValue)
        {
            query = query.Where(c => c.Credits >= minCredits.Value);
        }

        if (maxCredits.HasValue)
        {
            query = query.Where(c => c.Credits <= maxCredits.Value);
        }

        return query.OrderBy(c => c.Code).ToList().AsReadOnly();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public bool SubmitEnrollmentRequest(EnrollmentRequestModel request)
    {
        var course = GetCourse(request.CourseId);
        if (course is null || course.CurrentEnrollment >= course.MaxEnrollment)
        {
            return false;
        }

        // In a real application, this would persist to a database
        return true;
    }
}

