arguments.file_text:
@using UniversityCourseCatalog.Models

<div class="card h-100 shadow-sm border-0">
    <div class="card-body">
        <span class="badge bg-primary mb-2">@Course.DepartmentName</span>
        <h5 class="card-title">
            <a href="courses/@Course.Id" class="text-decoration-none text-dark">@Course.Title</a>
        </h5>
        <h6 class="card-subtitle mb-2 text-muted">@Course.Code &middot; @Course.Credits Credits</h6>
        <p class="card-text text-muted small">@Truncate(Course.Description, 120)</p>
    </div>
    <div class="card-footer bg-transparent border-0 d-flex justify-content-between align-items-center">
        <small class="text-muted">
            <strong>@Course.Instructor.Name</strong>
        </small>
        <a href="courses/@Course.Id" class="btn btn-sm btn-outline-primary">View Details</a>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength)
    {
        if (text.Length <= maxLength) return text;
        return string.Concat(text.AsSpan(0, maxLength).TrimEnd(), "…");
    }
}

@using UniversityCourseCatalog.Models

<div class="list-group-item list-group-item-action p-3">
    <div class="d-flex justify-content-between align-items-start">
        <div class="flex-grow-1">
            <div class="d-flex align-items-center mb-1">
                <span class="badge bg-secondary me-2">@Course.Code</span>
                <span class="badge bg-info me-2">@Course.Credits Credits</span>
                @if (Course.IsFeatured)
                {
                    <span class="badge bg-warning text-dark">Featured</span>
                }
            </div>
            <h5 class="mb-1">
