@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center py-5 mb-4 bg-primary text-white rounded-3">
    <h1 class="display-4 fw-bold">University Course Catalog</h1>
    <p class="lead mb-3">Explore our departments, discover courses, and start your enrollment today.</p>
    <a href="catalog" class="btn btn-light btn-lg me-2">Browse Courses</a>
    <a href="enroll" class="btn btn-outline-light btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row row-cols-1 row-cols-md-3 g-4">
        @foreach (var course in _featuredCourses)
        {
            <div class="col">
                <FeaturedCourseCard Course="course" />
            </div>
        }
    </div>
</section>

<section class="mb-5">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2 class="mb-0">Departments</h2>
        <a href="catalog" class="btn btn-sm btn-outline-primary">View All Courses</a>
    </div>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-3">
        @foreach (var dept in _departments)
        {
            <div class="col">
                <a href="catalog?departmentId=@dept.Id" class="card text-decoration-none h-100 shadow-sm border-0">
                    <div class="card-body">
                        <h5 class="card-title text-primary">@dept.Name</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@dept.Code</h6>
                        <p class="card-text text-muted small">@dept.Description</p>
                    </div>
                </a>
            </div>
        }
    </div>
</section>

@code {
    private IReadOnlyList<Course> _featuredCourses = [];
    private IReadOnlyList<Department> _departments = [];

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetDepartments();
    }
}

arguments.file_text:
@page "/catalog"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<CourseFilters Search="@Search" DepartmentId="@DepartmentId" MinCredits="@MinCredits" Departments="_departments" />

<div class="d-flex justify-content-between align-items-center mb-3">
    <p class="text-muted mb-0">
        Showing <strong>@_courses.Count</strong> course@(_courses.Count != 1 ? "s" : "")
        @if (!string.IsNullOrWhiteSpace(Search))
        {
            <span> matching &ldquo;@Search&rdquo;</span>
        }
        @if (DepartmentId.HasValue)
        {
            var dept = _departments.FirstOrDefault(d => d.Id == DepartmentId.Value);
            if (dept is not null)
            {
                <span> in <strong>@dept.Name</strong></span>
            }
        }
    </p>
</div>

@if (_courses.Count == 0)
{
    <div class="alert alert-info">
        No courses found matching your criteria. Try adjusting your filters or <a href="catalog">clear all filters</a>.
    </div>
}
else
{
    <div class="list-group">
        @foreach (var course in _courses)
        {
            <CourseListItem Course="course" />
        }
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
    [SupplyParameterFromQuery] public int? MinCredits { get; set; }

    private IReadOnlyList<Course> _courses = [];
    private IReadOnlyList<Department> _departments = [];

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
        _courses = CatalogService.GetCourses(Search, DepartmentId, MinCredits);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.FullName</strong>. Your enrollment request for
            <strong>@(_courses.FirstOrDefault(c => c.Id == _model.CourseId)?.Title ?? "the selected course")</strong>
            has been received.</p>
        <p>You will receive a confirmation at your university email. Please allow 2–3 business days for processing.</p>
        <hr />
        <a href="catalog" class="btn btn-outline-success me-2">Browse More Courses</a>
        <a href="enroll" class="btn btn-success">Submit Another Request</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card border-0 shadow-sm">
                <div class="card-body">
                    <p class="text-muted mb-4">
                        Fill out the form below to request enrollment in a course.
                        All fields marked with <span class="text-danger">*</span> are required.
                    </p>

                    <form method="post" @formname="enrollment">
                        <AntiforgeryToken />

                        <div class="mb-3">
                            <label for="fullName" class="form-label fw-semibold">
                                Full Name <span class="text-danger">*</span>
                            </label>
                            <input type="text" id="fullName" name="_model.FullName" value="@_model.FullName"
                                   class="form-control" required maxlength="100" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label fw-semibold">
                                Student ID <span class="text-danger">*</span>
                            </label>
                            <input type="text" id="studentId" name="_model.StudentId" value="@_model.StudentId"
                                   class="form-control" required placeholder="e.g., CS012345"
                                   pattern="^[A-Z]{2}\d{6}$" />
                            <div class="form-text">Format: 2 uppercase letters followed by 6 digits.</div>
                        </div>

                        <div class="mb-3">
                            <label for="email" class="form-label fw-semibold">
                                Email Address <span class="text-danger">*</span>
                            </label>
                            <input type="email" id="email" name="_model.Email" value="@_model.Email"
                                   class="form-control" required />
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label fw-semibold">
                                Course <span class="text-danger">*</span>
                            </label>
                            <select id="courseId" name="_model.CourseId" class="form-select" required>
                                <option value="">— Select a course —</option>
                                @foreach (var course in _courses)
                                {
                                    if (course.Id == _model.CourseId)
                                    {
                                        <option value="@course.Id" selected>@course.Code — @course.Title (@course.Credits cr.)</option>
                                    }
                                    else
                                    {
                                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                                    }
                                }
                            </select>
