@page "/catalog"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<CourseFilters Search="@Search" DepartmentId="@DepartmentId" MinCredits="@MinCredits" Departments="_departments" />

<div class="d-flex justify-content-between align-items-center mb-3">
    <p class="text-muted mb-0">
        Showing <strong>@_courses.Count</strong> course@(_courses.Count != 1 ? "s" : "")
        @if (!string.IsNullOrWhiteSpace(Search))
        {
            <span> matching &ldquo;@Search&rdquo;</span>
        }
        @if (DepartmentId.HasValue)
        {
            var dept = _departments.FirstOrDefault(d => d.Id == DepartmentId.Value);
            if (dept is not null)
            {
                <span> in <strong>@dept.Name</strong></span>
            }
        }
    </p>
</div>

@if (_courses.Count == 0)
{
    <div class="alert alert-info">
        No courses found matching your criteria. Try adjusting your filters or <a href="catalog">clear all filters</a>.
    </div>
}
else
{
    <div class="list-group">
        @foreach (var course in _courses)
        {
            <CourseListItem Course="course" />
        }
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
    [SupplyParameterFromQuery] public int? MinCredits { get; set; }

    private IReadOnlyList<Course> _courses = [];
    private IReadOnlyList<Department> _departments = [];

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
        _courses = CatalogService.GetCourses(Search, DepartmentId, MinCredits);
    }
}

