toolArgs.file_text:
@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.FullName</strong>. Your enrollment request for
            <strong>@(_courses.FirstOrDefault(c => c.Id == _model.CourseId)?.Title ?? "the selected course")</strong>
            has been received.</p>
        <p>You will receive a confirmation at your university email. Please allow 2–3 business days for processing.</p>
        <hr />
        <a href="catalog" class="btn btn-outline-success me-2">Browse More Courses</a>
        <a href="enroll" class="btn btn-success">Submit Another Request</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card border-0 shadow-sm">
                <div class="card-body">
                    <p class="text-muted mb-4">
                        Fill out the form below to request enrollment in a course.
                        All fields marked with <span class="text-danger">*</span> are required.
                    </p>

                    <form method="post" @formname="enrollment">
                        <AntiforgeryToken />

                        <div class="mb-3">
                            <label for="fullName" class="form-label fw-semibold">
                                Full Name <span class="text-danger">*</span>
                            </label>
                            <input type="text" id="fullName" name="_model.FullName" value="@_model.FullName"
                                   class="form-control" required maxlength="100" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label fw-semibold">
                                Student ID <span class="text-danger">*</span>
                            </label>
                            <input type="text" id="studentId" name="_model.StudentId" value="@_model.StudentId"
                                   class="form-control" required placeholder="e.g., CS012345"
                                   pattern="^[A-Z]{2}\d{6}$" />
                            <div class="form-text">Format: 2 uppercase letters followed by 6 digits.</div>
                        </div>

                        <div class="mb-3">
                            <label for="email" class="form-label fw-semibold">
                                Email Address <span class="text-danger">*</span>
                            </label>
                            <input type="email" id="email" name="_model.Email" value="@_model.Email"
                                   class="form-control" required />
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label fw-semibold">
                                Course <span class="text-danger">*</span>
                            </label>
                            <select id="courseId" name="_model.CourseId" class="form-select" required>
                                <option value="">— Select a course —</option>
                                @foreach (var course in _courses)
                                {
                                    if (course.Id == _model.CourseId)
                                    {
                                        <option value="@course.Id" selected>@course.Code — @course.Title (@course.Credits cr.)</option>
                                    }
                                    else
                                    {
                                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                                    }
                                }
                            </select>
                        </div>

                        <div class="mb-4">
                            <label for="comments" class="form-label fw-semibold">Comments (optional)</label>
                            <textarea id="comments" name="_model.Comments" class="form-control" rows="3"
                                      maxlength="500">@_model.Comments</textarea>
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    </form>
                </div>
            </div>
        </div>
        <div class="col-lg-4">
            <div class="card border-0 shadow-sm bg-light">
                <div class="card-body">
                    <h5 class="card-title">Need Help?</h5>
                    <p class="card-text small text-muted">
                        If you have questions about enrollment or need assistance, contact the Registrar's Office.
                    </p>
                    <dl class="small mb-0">
                        <dt>Email</dt>
                        <dd>registrar@university.edu</dd>
                        <dt>Phone</dt>
                        <dd>(555) 123-4567</dd>
                        <dt>Hours</dt>
                        <dd>Mon–Fri, 8:00 AM – 5:00 PM</dd>
                    </dl>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    [SupplyParameterFromForm]
    private EnrollmentRequestModel _model { get; set; } = new();

    private IReadOnlyList<Course> _courses = [];
    private bool _submitted;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();

        if (CourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? ""))
        {
            if (_model.CourseId > 0 && !string.IsNullOrWhiteSpace(_model.FullName))
            {
                _submitted = CatalogService.SubmitEnrollmentRequest(_model);
            }
        }
    }

    [CascadingParameter]
    private HttpContext? HttpContextAccessor { get; set; }
}

